import json
with open('/app/resources/treasury_bulletin_2013_06.json', 'r') as f:
    data = json.load(f)

# List all table names
def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == 'title' and isinstance(v, str) and len(v) < 100:
                print(f'Table: {v}')
            find_tables(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_tables(item, f'{path}[{i}]')

find_tables(data)
